output:
 Kim Silva, a retired teacher from the American School for the Deaf, taught her three cats sign language. Her method involved giving them treats when they perform the sign correctly. Her cats are able to understand words like "stay", "sit", "shake" and "dance". 


module.exports = function(KEY, full Article) {
    var summary = article => {
        var text = article.replace(/\\n|\\t/g, '').split(' ');
        var words = text[0].split('.');
        var principalWords = 'The cats are now able to understand her signs for words such as 'stay', 'sit', 'shake', 'dance' and many more.'
          .replace(' ', '')
          .split(',');
        var summary = '';
        var i = 0;

       words.forEach(word => (word.length > 10 && (i++, summary += `${word.charAt(0)}${word.length > 15 ? ', ' : ' '}${words[i]}));

        return summary.trim();
      };
